#ifndef SRC_NET_REV_REV_EXEC_H
#define SRC_NET_REV_REV_EXEC_H

/*
 * What every revision's executor (src/net/rev/<rev>/<rev>_exec.c, GENERATED by
 * tools/rev_exec_gen.py) is written against: the adapters, the writers, the
 * info streams' entry points, and the one rule every arm applies.
 */

#include "net/login/login_osrs.h"
#include "net/proto/proto_adapt.h"
#include "net/proto/proto_info.h"
#include "net/proto/proto_out.h"
#include "net/proto/proto_out_writers.h"
#include "net/rev/gameproto_revisions.h"
#include "net/rev/packets/pkt_player_appearance.h"
#include "net/rev/rev_list.h"
#include "streams/info_rs.h"

#include "rsprot_exec.h"
#include "streams/npc_info.h"
#include "streams/player_info.h"
#include "streams/worldentity_info.h"

/*
 * A payload decoded when its codec ran clean AND read it to the end. A prot's
 * table states its size, but a variable one is only as long as the server
 * made it: bytes left over are a layout this codec does not know, not a
 * packet to act on.
 */
static inline int
rev_exec_whole(RsprotExec const* x, RsprotBuf const* b, int len)
{
    return rsprot_exec_ok(x) && !b->err && b->rpos == len;
}

#endif
